            : 'bg-[#f1f1ec] text-[#6e6e66]'
        }`}
      >
        {r.role}
      </span>
    </div>
  )
}

function Empty({ children }: { children: React.ReactNode }) {
  return <p className="text-sm text-[#8a8a82]">{children}</p>
}

